---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Banner: An announcement on a tint of its tone, with its own line drawing.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change banner.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './banner.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" draws it in the Soft style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft") */
  'data-style'?: 'soft';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', 'wide', className]} data-c="banner" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<div class="dm bnx-dm"><div class="dm-main bnx-slot">
  <div class="bnx" role="region" data-tone="accent" data-art="layers" aria-label="Announcement">
    <div class="bnx-art" aria-hidden="true"></div>
    <div class="bnx-tx">
      <span class="bnx-eb"><span>New</span></span>
      <p class="bnx-t"><span>Memory that carries across threads</span></p>
      <p class="bnx-d"><span>Agents keep what they learn about your project, so you only explain things once.</span></p>
      <div class="bnx-acts"><button class="pill primary sm bnx-go"><span>Turn on memory</span></button><button class="bnx-lk"><span>What it keeps</span></button></div>
    </div>
  </div>
</div>
<div class="demo"><div class="seg2" role="group" aria-label="Banner style"><button aria-pressed="true" data-v="0">Accent</button><button aria-pressed="false" data-v="1">Violet</button><button aria-pressed="false" data-v="2">Green</button><button aria-pressed="false" data-v="3">Amber</button></div></div>
</div>
  </Fragment></div>
</div>
<script>
  import './banner.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Banner ---------- */
/* an announcement on a tint of its tone: an eyebrow, a title, a line of text and its actions on the left, and one of four line
   drawings on the right, drawn as a hairline with a few construction lines, the way Blueprint draws everything. Each tone
   names three colours: --dm-bnx-m draws the art (3:1 on the fill), --dm-bnx-c writes the eyebrow (4.5:1) and --dm-bnx-f is what
   the fill is a tint of. The fill is solid, so the close button and the art's own faces can wear it too. It has no border:
   the tint is its edge */
.bnx-slot{width:100%}
.bnx{position:relative;width:100%;min-height:176px;display:flex;flex-direction:column;justify-content:center;overflow:hidden;border-radius:var(--dm-r-card);container:bnx/inline-size;isolation:isolate;
  --dm-bnx-m:var(--dm-accent-mark);--dm-bnx-c:var(--dm-accent-fg);--dm-bnx-f:var(--dm-accent);--dm-bnx-k:10%;--dm-bnx-ka:var(--dm-bnx-k);
  --dm-bnx-bg:color-mix(in srgb,var(--dm-bnx-f) var(--dm-bnx-ka),var(--dm-surface));
  background:var(--dm-bnx-bg);transition:background-color var(--dm-t-slow) var(--dm-ease)}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]) .bnx{--dm-bnx-k:14%}}
:root[data-theme="dark"] .bnx{--dm-bnx-k:14%}
.bnx[data-tone="neutral"]{--dm-bnx-m:var(--dm-muted);--dm-bnx-c:var(--dm-fg2);--dm-bnx-bg:var(--dm-chip)}
.bnx[data-tone="blue"]{--dm-bnx-m:var(--dm-pb);--dm-bnx-c:var(--dm-pb);--dm-bnx-f:var(--dm-pb);--dm-bnx-ka:var(--dm-bnx-k)}
.bnx[data-tone="violet"]{--dm-bnx-m:var(--dm-pl);--dm-bnx-c:var(--dm-pl);--dm-bnx-f:var(--dm-pl);--dm-bnx-ka:var(--dm-bnx-k)}
.bnx[data-tone="green"]{--dm-bnx-m:var(--dm-pm);--dm-bnx-c:var(--dm-pm);--dm-bnx-f:var(--dm-pm);--dm-bnx-ka:var(--dm-bnx-k)}
.bnx[data-tone="amber"]{--dm-bnx-m:var(--dm-py);--dm-bnx-c:var(--dm-py);--dm-bnx-f:var(--dm-py);--dm-bnx-ka:var(--dm-bnx-k)}
/* the text keeps clear of the art: its right padding is the art's width */
.bnx-tx{position:relative;z-index:1;display:flex;flex-direction:column;align-items:flex-start;padding:var(--dm-s-5) calc(min(42%,300px) + var(--dm-s-2)) var(--dm-s-5) var(--dm-s-6)}
.bnx-eb{font-size:12px;font-weight:500;line-height:16px;color:var(--dm-bnx-c);transition:color var(--dm-t-slow) var(--dm-ease)}
.bnx-t{margin:var(--dm-s-2) 0 0;font-size:14px;font-weight:500;line-height:20px;color:var(--dm-fg);text-wrap:balance}
.bnx-d{margin:var(--dm-s-1) 0 0;font-size:13px;line-height:20px;color:var(--dm-fg2);text-wrap:pretty}
.bnx-acts{display:flex;flex-wrap:wrap;align-items:center;gap:var(--dm-s-2) var(--dm-s-4);margin-top:var(--dm-s-4)}
.bnx-lk{display:inline-flex;align-items:center;height:28px;font-size:13px;color:var(--dm-fg);text-decoration:underline;text-decoration-color:color-mix(in srgb,currentColor 35%,transparent);text-underline-offset:3px;transition:text-decoration-color var(--dm-t-fast)}
@media (hover:hover) and (pointer:fine){.bnx-lk:hover{text-decoration-color:currentColor}}
/* on a coloured banner the primary button is white in light mode, with the text colour on it, so it stands out from the tint
   in every tone; in dark mode, where the tint is deep, it stays the accent. A neutral (grey) banner keeps the accent */
.bnx:not([data-tone="neutral"]) .bnx-go{background:var(--dm-surface);color:var(--dm-fg);box-shadow:var(--dm-shadow)}
@media (hover:hover) and (pointer:fine){.bnx:not([data-tone="neutral"]) .bnx-go:hover{background:var(--dm-surface);box-shadow:var(--dm-shadow-pop)}}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]) .bnx .bnx-go{background:var(--dm-accent);color:var(--dm-on-accent);box-shadow:none}
  @media (hover:hover) and (pointer:fine){:root:not([data-theme="light"]) .bnx .bnx-go:hover{background:var(--dm-accent-2);box-shadow:none}}}
:root[data-theme="dark"] .bnx .bnx-go{background:var(--dm-accent);color:var(--dm-on-accent);box-shadow:none}
@media (hover:hover) and (pointer:fine){:root[data-theme="dark"] .bnx .bnx-go:hover{background:var(--dm-accent-2);box-shadow:none}}
/* an optional close button in the top right corner (the card here leaves it out) */
.bnx-x{position:absolute;top:var(--dm-s-2);right:var(--dm-s-2);z-index:2;width:28px;height:28px;background:var(--dm-bnx-bg)}
@media (hover:hover) and (pointer:fine){.bnx-x:hover{background:color-mix(in srgb,var(--dm-fg) 8%,var(--dm-bnx-bg))}}
/* the art: a 240 by 160 drawing at its own size in the middle of the area on the right, cropped by it and faded in from the
   text's side, so a narrower banner shows less of it rather than a smaller one */
.bnx-art{position:absolute;top:0;right:0;bottom:0;width:min(42%,300px);overflow:hidden;pointer-events:none;-webkit-mask-image:linear-gradient(90deg,transparent,#000 var(--dm-s-8));mask-image:linear-gradient(90deg,transparent,#000 var(--dm-s-8))}
.bnx-svg{position:absolute;left:50%;top:50%;width:240px;height:160px;margin:-80px 0 0 -120px;overflow:visible;display:block}
.bnx-svg .ln{fill:none;stroke:var(--dm-bnx-m);stroke-width:1;stroke-linejoin:round;stroke-dasharray:1 1;stroke-dashoffset:0;animation:bnxdraw 1.1s var(--dm-ease) calc(160ms + var(--dm-d,0) * 60ms) backwards}
.bnx-svg .ac{stroke-width:1.5}
.bnx-svg .gd{fill:none;stroke:var(--dm-bnx-m);stroke-width:1;stroke-dasharray:2 3;opacity:.45;animation:bnxfade .9s var(--dm-ease) 60ms backwards}
/* the faces under the lines wear the fill, so what is in front hides what is behind once it is drawn */
.bnx-svg .pl{fill:var(--dm-bnx-bg);stroke:none;animation:bnxfade .6s var(--dm-ease) .5s backwards}
.bnx-svg .lg{fill:var(--dm-bnx-m);animation:bnxfade .6s var(--dm-ease) .7s backwards}
.bnx-svg .dt{fill:none;stroke:var(--dm-bnx-m);stroke-width:2;stroke-linecap:round;stroke-dasharray:0 5;animation:bnxfade .9s var(--dm-ease) .4s backwards}
@keyframes bnxdraw{from{stroke-dashoffset:1}}
@keyframes bnxfade{from{opacity:0}}
/* under the pointer the drawing pulls apart a little: each part moves by its depth (--dm-z), with no blur */
.bnx-svg .z{transition:transform var(--dm-t-slow) var(--dm-ease)}
@media (hover:hover) and (pointer:fine){.bnx:hover .bnx-svg .z{transform:translate(calc(var(--dm-z,0) * 1px),calc(var(--dm-z,0) * -2.5px))}}
/* the card: the banner with a switcher under it that flips through the four styles, the two kept together and centred */
.dm.bnx-dm{min-height:0;gap:var(--dm-s-5);justify-content:center}
.dm.bnx-dm>.dm-main{margin-block:0}
/* a phone, or any narrow column: the art becomes a shorter strip across the top that fades out before the text starts,
   so nothing is drawn behind the words. The drawing is shown at six tenths, so all of it fits in the strip, with its lines
   thickened to stay a hairline */
@container bnx (max-width:479px){
  /* on a phone the picture takes a taller band of its own over the text, and lines up with the text's left edge (owner, 4 Nov) */
  .bnx-art{left:0;bottom:auto;width:auto;height:128px;-webkit-mask-image:linear-gradient(#000 104px,transparent 128px);mask-image:linear-gradient(#000 104px,transparent 128px)}
  .bnx-svg{top:68px;left:var(--dm-bnx-al,calc(var(--dm-s-5) - 27px));margin-left:0;transform-origin:0 50%;transform:scale(.72)}
  .bnx-svg :is(.ln,.gd){stroke-width:1.6}
  .bnx-svg .ac{stroke-width:2.4}
  .bnx-svg .dt{stroke-width:3.2}
  .bnx-tx{padding:124px var(--dm-s-5) var(--dm-s-6)}
}
@media (prefers-reduced-motion:reduce){.bnx-svg *{animation:none!important}.bnx-svg .z{transform:none!important}}
/* Blueprint: square, and the eyebrow as a small capital label */
:root:not([data-style="soft"]) .bnx:is(:not([data-tone]),[data-tone="accent"]):not(:where([data-style="soft"],[data-style="soft"] *)){--dm-bnx-ka:20%}
/* a Blueprint banner has an edge in its own colour, like the sheet's other boxes (owner, 10 Nov) */
:root:not([data-style="soft"]) .bnx:not(:where([data-style="soft"],[data-style="soft"] *)){box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-bnx-f,var(--dm-bnx-m)) 70%,var(--dm-fg))}
/* in light mode the agent's tint is a clear lime, not a cream, with an olive edge (owner, 10 Nov) */
:root:not([data-style="soft"])[data-theme="light"] :is(.pill.soft.ecx-ask,.six-ans):not(:where([data-style="soft"],[data-style="soft"] *)){--dm-ask-edge:color-mix(in srgb,var(--dm-accent) 70%,var(--dm-fg));background:color-mix(in srgb,var(--dm-accent) 24%,var(--dm-surface));box-shadow:inset 0 0 0 1px var(--dm-ask-edge)}
@media (prefers-color-scheme:light){:root:not([data-style="soft"]):not([data-theme="dark"]) :is(.pill.soft.ecx-ask,.six-ans):not(:where([data-style="soft"],[data-style="soft"] *)){--dm-ask-edge:color-mix(in srgb,var(--dm-accent) 70%,var(--dm-fg));background:color-mix(in srgb,var(--dm-accent) 24%,var(--dm-surface));box-shadow:inset 0 0 0 1px var(--dm-ask-edge)}}
@media (prefers-color-scheme:dark){:root:not([data-style="soft"]):not([data-theme="light"]) .bnx:is(:not([data-tone]),[data-tone="accent"]):not(:where([data-style="soft"],[data-style="soft"] *)){--dm-bnx-ka:9%}}
:root:not([data-style="soft"])[data-theme="dark"] .bnx:is(:not([data-tone]),[data-tone="accent"]):not(:where([data-style="soft"],[data-style="soft"] *)){--dm-bnx-ka:9%}
:root:not([data-style="soft"]) .bnx-eb:not(:where([data-style="soft"],[data-style="soft"] *)){font-size:11px;letter-spacing:.06em;text-transform:uppercase}
/* Blueprint draws its lines with square ends, so the dotted route is square dots */
:root:not([data-style="soft"]) .bnx-svg .dt:not(:where([data-style="soft"],[data-style="soft"] *)){stroke-dasharray:2 3}
@container bnx (max-width:479px){:root:not([data-style="soft"]) .bnx-svg .dt:not(:where([data-style="soft"],[data-style="soft"] *)){stroke-dasharray:3.2 4.8}}

// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
import { $, $$, DM, I, REDUCE, seg, swap } from '../core/core.js';
/* the four drawings, each 240 by 160 and written as plain paths, all in one isometric view on a floor grid, with their
   drawn box centred in it: layers (three plates of a stack, pulled apart, the bottom one standing on the floor), steps (a staircase climbing to a flag, on a floor
   that follows its footprint), tools (five tool tiles, Slack, GitHub, Linear, Gmail and Apollo, each with its mark on top)
   and path (a dotted route across the floor to a raised tile). .ln lines draw themselves in, in the order --d gives; .gd
   are the construction lines and the floor, dashed, which fade in; .pl are faces in the banner's fill that hide what is
   behind them; .lg are the tools' marks and .dt the dotted route; each .z group moves by its depth --z under the pointer. */
const BNX_ART = {
  layers:"<g class=\"gds\"><path class=\"gd\" d=\"M120 51L36.9 99M140.8 63L57.6 111M161.6 75L78.4 123M182.4 87L99.2 135M203.1 99L120 147M120 51L203.1 99M99.2 63L182.4 111M78.4 75L161.6 123M57.6 87L140.8 135M36.9 99L120 147\"/></g><g class=\"gds\"><path class=\"gd\" d=\"M78.4 43L78.4 93M161.6 43L161.6 93M120 67L120 117\"/></g><g class=\"z\" style=\"--dm-z:0\"><path class=\"pl\" d=\"M120 69L161.6 93L161.6 99L120 123L78.4 99L78.4 93Z\"/><path class=\"ln\" style=\"--dm-d:0\" pathLength=\"1\" d=\"M120 69L161.6 93L120 117L78.4 93Z\"/><path class=\"ln\" style=\"--dm-d:1\" pathLength=\"1\" d=\"M161.6 93L161.6 99L120 123L78.4 99L78.4 93\"/><path class=\"ln\" style=\"--dm-d:2\" pathLength=\"1\" d=\"M120 117L120 123\"/></g><g class=\"z\" style=\"--dm-z:1\"><path class=\"pl\" d=\"M120 41L161.6 65L161.6 71L120 95L78.4 71L78.4 65Z\"/><path class=\"ln\" style=\"--dm-d:3\" pathLength=\"1\" d=\"M120 41L161.6 65L120 89L78.4 65Z\"/><path class=\"ln\" style=\"--dm-d:4\" pathLength=\"1\" d=\"M161.6 65L161.6 71L120 95L78.4 71L78.4 65\"/><path class=\"ln\" style=\"--dm-d:5\" pathLength=\"1\" d=\"M120 89L120 95\"/></g><g class=\"z\" style=\"--dm-z:2\"><path class=\"pl\" d=\"M120 13L161.6 37L161.6 43L120 67L78.4 43L78.4 37Z\"/><path class=\"ln\" style=\"--dm-d:6\" pathLength=\"1\" d=\"M120 13L161.6 37L120 61L78.4 37Z\"/><path class=\"ln\" style=\"--dm-d:7\" pathLength=\"1\" d=\"M161.6 37L161.6 43L120 67L78.4 43L78.4 37\"/><path class=\"ln\" style=\"--dm-d:8\" pathLength=\"1\" d=\"M120 61L120 67\"/><path class=\"ln ac\" style=\"--dm-d:9\" pathLength=\"1\" d=\"M120 23.8L142.9 37L120 50.2L97.1 37Z\"/></g>",
